def clean(df):
    region_mapping = {
        "north": "North",
        "Nort": "North",
        "east": "East",
        "Suoth": "South",
        "Wst": "West"
    }
    df['Region'] = df['Region'].replace(region_mapping)
    return df

def answer(df):
    return df[df['Category'] == 'Electronics'].groupby('Region')['Revenue'].sum().to_dict()
